import {WARNING,FIELDS,SAMPLE,compare,validateApplication} from './engine.js';
const $=s=>document.querySelector(s), queue=[], manifest=new Map();
let selected=-1, worker=null, workerPromise=null, busy=false, cancelled=false;
const form=$('#application');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function message(s){$('#message').hidden=!s;$('#message').textContent=s;}
function getApp(){const d=Object.fromEntries(new FormData(form));d.imported=form.elements.imported.checked;return d;}
function sync(){if(selected>=0&&!busy){queue[selected].app=getApp(); if(queue[selected].result){queue[selected].result=null;queue[selected].status='Details changed — recompare';renderResults();renderQueue();}}}
function fill(app){for(const [k] of FIELDS)form.elements[k].value=app[k]??'';form.elements.imported.checked=!!app.imported;form.elements.origin.required=!!app.imported;}
function renderQueue(){ $('#queueCount').textContent=`${queue.length} label${queue.length===1?'':'s'}`;$('#queue').classList.toggle('queue-scroll',queue.length>4);$('#queue').innerHTML=queue.map((r,i)=>`<button class="queue-item ${i===selected?'active':''}" data-index="${i}" ${busy?'disabled':''}><span>${escape(r.file.name)}</span><small>${escape(r.status||'Ready')}</small></button>`).join('');$('#verify').disabled=busy||selected<0;$('#batch').disabled=busy||!queue.length;$('#demo').disabled=busy;$('#files').disabled=busy;$('#manifest').disabled=busy;$('#rotate').disabled=busy;$('#appFields').disabled=busy||selected<0;$('#clear').disabled=busy;}
function select(i){if(busy)return; selected=i;const r=queue[i];fill(r.app);$('#selectedName').textContent=r.file.name;$('#previewWrap').hidden=false;$('#preview').src=r.url;$('#preview').style.transform=`rotate(${r.rotation}deg)`;$('#notes').value=r.notes||'';$('#visualReview').checked=!!r.visual;renderQueue();renderResults();}
$('#queue').addEventListener('click',e=>{const b=e.target.closest('[data-index]');if(b)select(Number(b.dataset.index));});
form.addEventListener('input',sync);form.addEventListener('change',()=>{form.elements.origin.required=form.elements.imported.checked;sync();});form.addEventListener('submit',e=>e.preventDefault());
function add(files){if(busy)return;message('');const errors=[];for(const file of files){if(queue.length>=300){errors.push('Batch limit is 300 images.');break;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){errors.push(`${file.name}: use PNG, JPG or WebP.`);continue;}if(file.size>15*1024*1024){errors.push(`${file.name}: file exceeds 15 MB.`);continue;}if(queue.some(r=>r.file.name===file.name)){errors.push(`${file.name}: already in the queue; use unique filenames.`);continue;}queue.push({file,url:URL.createObjectURL(file),app:{...manifest.get(file.name)},rotation:0,notes:'',visual:false});}if(queue.length&&selected<0)select(0);renderQueue();if(errors.length)message(errors.join(' '));}
$('#files').addEventListener('change',e=>{add(e.target.files);e.target.value='';});
for(const name of ['dragover','dragleave','drop'])$('#dropzone').addEventListener(name,e=>{e.preventDefault();$('#dropzone').classList.toggle('drag',name==='dragover');if(name==='drop')add(e.dataTransfer.files);});
$('#manifest').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('Application JSON must be under 2 MB.');const records=JSON.parse(await file.text());if(!Array.isArray(records)||records.length>300)throw Error('Use an array of up to 300 application records.');const staged=new Map();for(const a of records){if(!a||typeof a.filename!=='string'||!a.filename.trim())throw Error('Each record needs a filename.');if(staged.has(a.filename))throw Error(`Duplicate filename: ${a.filename}`);if(a.imported!==undefined&&typeof a.imported!=='boolean')throw Error(`imported must be true or false for ${a.filename}.`);const clean={filename:a.filename,imported:!!a.imported};for(const [k]of FIELDS){if(a[k]!==undefined&&!['string','number'].includes(typeof a[k]))throw Error(`Invalid ${k} for ${a.filename}.`);clean[k]=String(a[k]??'').slice(0,1000);}const errors=validateApplication(clean);if(errors.length)throw Error(`${a.filename}: ${errors.join(' ')}`);staged.set(a.filename,clean);}for(const [k,a]of staged)manifest.set(k,a);let matched=0;for(const r of queue)if(manifest.has(r.file.name)){r.app={...manifest.get(r.file.name)};r.result=null;r.status='Application imported';matched++;}if(selected>=0)select(selected);message(`Imported ${staged.size} application records. ${matched} queued images matched by filename. Upload the matching images to process the rest.`);}catch(err){message(`Could not import applications: ${err.message}`);}finally{e.target.value='';}});
$('#rotate').addEventListener('click',()=>{if(selected<0)return;const r=queue[selected];r.rotation=(r.rotation+90)%360;r.result=null;r.status='Rotated — reprocess';select(selected);});
async function imageCanvas(r){const img=new Image();img.src=r.url;await img.decode();if(img.naturalWidth*img.naturalHeight>60000000)throw Error('Image dimensions exceed 60 megapixels. Resize and try again.');const angle=r.rotation*Math.PI/180,sw=r.rotation%180?img.naturalHeight:img.naturalWidth,sh=r.rotation%180?img.naturalWidth:img.naturalHeight;const scale=Math.min(1,2200/Math.max(sw,sh));const canvas=document.createElement('canvas');canvas.width=Math.round(sw*scale);canvas.height=Math.round(sh*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(angle);ctx.drawImage(img,-img.naturalWidth*scale/2,-img.naturalHeight*scale/2,img.naturalWidth*scale,img.naturalHeight*scale);return canvas;}
async function getWorker(){if(worker)return worker;if(!window.Tesseract)throw Error('Image reader could not load. Reload the page.');if(!workerPromise)workerPromise=Tesseract.createWorker('eng',1,{workerPath:'/vendor/worker.min.js',corePath:'/vendor/core',langPath:'/vendor/lang',gzip:true,workerBlobURL:false,logger:m=>{if(busy){$('#progress').value=m.progress??0;$('#progressText').textContent=(m.status==='recognizing text'?'Reading label text':m.status||'Preparing image reader')+'…';}}}).then(w=>{worker=w;return w;}).catch(e=>{workerPromise=null;throw e;});return workerPromise;}
async function readOne(r){const started=performance.now();r.status='Reading…';renderQueue();const w=await getWorker();if(cancelled)return;const canvas=await imageCanvas(r);await w.setParameters({tessedit_pageseg_mode:'3',preserve_interword_spaces:'1'});const {data}=await w.recognize(canvas);if(cancelled)return;if(!data.text.trim())throw Error('No readable text found. Use a sharper image or rotate it.');r.text=data.text;r.originalText=data.text;r.confidence=data.confidence;r.edited=false;r.visual=false;r.result=compare(r.text,r.app,r.confidence);r.elapsed=(performance.now()-started)/1000;r.status=r.result.needsReview?`${r.result.needsReview} to review`:'Text checks match';r.checkedAt=new Date().toISOString();}
async function run(all){if(busy||selected<0)return;queue[selected].app=getApp();const work=all?queue:[queue[selected]];const invalid=work.map(r=>({r,errors:validateApplication(r.app)})).filter(x=>x.errors.length);if(invalid.length){message(`${invalid[0].r.file.name}: ${invalid[0].errors.join(' ')}${invalid.length>1?` ${invalid.length} labels need application details.`:''}`);select(queue.indexOf(invalid[0].r));return;}message('');busy=true;cancelled=false;$('#progressWrap').hidden=false;renderQueue();let done=0;try{for(const r of work){if(cancelled)break;try{await readOne(r);if(!cancelled)done++;}catch(err){r.status='Reading failed';r.error=err.message;r.result=null;message(`${r.file.name}: ${err.message}`);}renderQueue();}if(cancelled)message(`Processing cancelled. ${done} completed result(s) kept.`);else if(work.length>1)message(`Batch finished: ${done} of ${work.length} images processed. Select each label to review its findings.`);}finally{busy=false;$('#progressWrap').hidden=true;renderQueue();renderResults();if(queue[selected].result)$('#results').scrollIntoView({behavior:'smooth',block:'start'});}}
$('#verify').addEventListener('click',()=>run(false));$('#batch').addEventListener('click',()=>run(true));
$('#cancel').addEventListener('click',()=>{cancelled=true;if(worker){worker.terminate();worker=null;workerPromise=null;}message('Cancelling image reading…');});
function renderResults(){const r=queue[selected];$('#results').hidden=!r?.result;if(!r?.result)return;const result=r.result;$('#resultHeading').textContent=result.needsReview?'Some details need a closer look':'Text checks match — visual review remains';$('#resultSummary').textContent=`${r.file.name} · ${r.edited?'Reviewer-corrected text':'Original OCR text'} · ${new Date(r.checkedAt).toLocaleString()}`;$('#resultMetrics').innerHTML=`<div class="metric"><strong>${result.matched}</strong>Text checks matched</div><div class="metric"><strong>${result.needsReview}</strong>Need review</div><div class="metric"><strong>${Math.round(r.confidence)}%</strong>OCR confidence</div><div class="metric"><strong>${r.elapsed.toFixed(1)}s</strong>Image reading + comparison${r.elapsed>5?' · above 5s target':''}</div>`;
const names={match:'Match',review:'Review',manual:'Visual check',skip:'Not compared'};$('#checks').innerHTML=result.rows.map(row=>`<tr><td>${escape(row.label)}</td><td>${escape(row.expected)}</td><td>${escape(row.observed||row.detail)}${row.observed?`<small>${escape(row.detail)}</small>`:''}</td><td><span class="badge ${row.status}">${names[row.status]}</span></td></tr>`).join('');$('#ocrText').value=r.text;$('#notes').value=r.notes;$('#visualReview').checked=r.visual;}
$('#recompare').addEventListener('click',()=>{if(busy||selected<0)return;const r=queue[selected];r.text=$('#ocrText').value;r.edited=r.text!==r.originalText;r.result=compare(r.text,r.app,r.confidence);r.status=r.result.needsReview?`${r.result.needsReview} to review`:'Text checks match';r.checkedAt=new Date().toISOString();renderResults();renderQueue();});
$('#notes').addEventListener('input',()=>{if(selected>=0)queue[selected].notes=$('#notes').value;});$('#visualReview').addEventListener('change',()=>{if(selected>=0)queue[selected].visual=$('#visualReview').checked;});
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').addEventListener('click',()=>{const report={application:'LabelLens',version:'1.0.0',exportedAt:new Date().toISOString(),purpose:'Comparison aid; not a compliance decision',labels:queue.map(r=>({filename:r.file.name,application:r.app,status:r.status,elapsedSeconds:r.elapsed,ocrConfidence:r.confidence,originalOCR:r.originalText,reviewedText:r.text,textEdited:!!r.edited,visualCheckRecorded:!!r.visual,notes:r.notes,checkedAt:r.checkedAt,comparison:r.result,error:r.error}))};download(JSON.stringify(report,null,2),'labellens-review.json','application/json');});
$('#print').addEventListener('click',()=>window.print());
$('#clear').addEventListener('click',()=>{if(busy)return;for(const r of queue)URL.revokeObjectURL(r.url);queue.length=0;manifest.clear();selected=-1;form.reset();$('#appFields').disabled=true;$('#selectedName').textContent='Select a label to enter its application details.';$('#previewWrap').hidden=true;$('#results').hidden=true;message('');renderQueue();});
$('#demo').addEventListener('click',async()=>{try{message('');let i=queue.findIndex(r=>r.file.name==='old-tom.png');if(i<0){const response=await fetch('/samples/old-tom.png');if(!response.ok)throw Error('Sample could not load.');manifest.set('old-tom.png',SAMPLE);add([new File([await response.blob()],'old-tom.png',{type:'image/png'})]);i=queue.length-1;}select(i);message('Sample loaded with matching application details. Select “Read & compare label” to run real OCR on the sample artwork.');}catch(e){message(e.message);}});
// Warm the self-hosted model while the reviewer enters application details.
if('requestIdleCallback'in window)requestIdleCallback(()=>getWorker().catch(()=>{}),{timeout:2000});else setTimeout(()=>getWorker().catch(()=>{}),1000);
